import math

def catalan_number(n):
    # Using the formula: C_n = (1/(n+1)) * binomial(2n, n)
    return math.comb(2 * n, n) // (n + 1)

def sum(a, b):
    total = 0
    for i in range(1, min(a, b) + 1):
        if a % i == 0 and b % i == 0:
            total += i
    return total

def check_monthnumb_number(n):
    # Return True if the month has 31 days, False otherwise
    months_with_31_days = {1, 3, 5, 7, 8, 10, 12}
    return n in months_with_31_days

def all_Characters_Same(s):
    if not s:
        return True
    return all(c == s[0] for c in s)

def len_log(words):
    if not words:
        return 0
    return max(len(word) for word in words)

def first_non_repeating_character(s):
    """
    Returns the first non-repeated character in the string.
    If no such character exists, returns None.
    """
    # Count occurrences of each character
    char_count = {}
    for char in s:
        char_count[char] = char_count.get(char, 0) + 1

    # Find the first character with count 1
    for char in s:
        if char_count[char] == 1:
            return char

    return None

def Find_Min_Length(list_of_lists):
    if not list_of_lists:
        return 0
    return min(len(lst) for lst in list_of_lists)

def flip_case(string: str) -> str:
    """ For a given string, flip lowercase characters to uppercase and uppercase to lowercase.
    >>> flip_case('Hello')
    'hELLO'
    """
    return string.swapcase()

def Find_Max_Length(lst):
    if not lst:
        return 0
    return max(len(sublist) for sublist in lst)

import math

def circle_circumference(radius):
    return 2 * math.pi * radius

import re

def text_lowercase_underscore(s):
    return bool(re.fullmatch(r'[a-z]+(_[a-z]+)+', s))

def check_monthnumber_number(month):
    # Months with 30 days are April (4), June (6), September (9), November (11)
    return month in {4, 6, 9, 11}

def count_reverse_pairs(lst):
    count = 0
    n = len(lst)
    for i in range(n):
        for j in range(i + 1, n):
            if lst[i] == lst[j][::-1]:
                count += 1
    return count

def diff_even_odd(lst):
    first_even = None
    first_odd = None
    for num in lst:
        if num % 2 == 0 and first_even is None:
            first_even = num
        elif num % 2 != 0 and first_odd is None:
            first_odd = num
        if first_even is not None and first_odd is not None:
            break
    return first_even - first_odd

def occurance_substring(s, sub):
    start = s.find(sub)
    if start == -1:
        return None
    end = start + len(sub)
    return (sub, start, end)

def unique_product(lst):
    unique_nums = set(lst)
    result = 1
    for num in unique_nums:
        result *= num
    return result

def cumulative_sum(tuples_list):
    """
    Returns the cumulative sum of all numeric values in the given tuple list.
    """
    return sum(sum(t) for t in tuples_list)

def even_odd_count(num):
    """Given an integer. return a tuple that has the number of even and odd digits respectively.

     Example:
        even_odd_count(-12) ==> (1, 1)
        even_odd_count(123) ==> (1, 2)
    """
    num_str = str(abs(num))
    even_count = 0
    odd_count = 0
    for char in num_str:
        digit = int(char)
        if digit % 2 == 0:
            even_count += 1
        else:
            odd_count += 1
    return (even_count, odd_count)

def greatest_common_divisor(a: int, b: int) -> int:
    """ Return a greatest common divisor of two integers a and b
    >>> greatest_common_divisor(3, 5)
    1
    >>> greatest_common_divisor(25, 15)
    5
    """
    while b:
        a, b = b, a % b
    return abs(a)

def max_aggregate(lst):
    totals = {}
    for name, score in lst:
        totals[name] = totals.get(name, 0) + score
    best_name = max(totals, key=totals.get)
    return (best_name, totals[best_name])

from itertools import combinations_with_replacement

def combinations_colors(lst, n):
