def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n < 2:
            return False
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                return False
        return True

    # Generate all primes up to a (inclusive)
    primes = [i for i in range(2, a + 1) if is_prime(i)]

    # Check all combinations of three primes (repetition allowed)
    for i in primes:
        for j in primes:
            for k in primes:
                if i * j * k == a:
                    return True
    return False

def remove_kth_element(lst, k):
    # Remove the k-th element (1-indexed) from the list
    return lst[:k-1] + lst[k:]

def jacobsthal_num(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1
    a, b = 0, 1
    for _ in range(2, n + 1):
        a, b = b, b + 2 * a
    return b

def get_coordinates(coord):
    x, y = coord
    result = []
    for dx in range(-1, 2):
        for dy in range(-1, 2):
            result.append([x + dx, y + dy])
    return result

def index_multiplication(tuple1, tuple2):
    return tuple(
        tuple(a * b for a, b in zip(t1, t2))
        for t1, t2 in zip(tuple1, tuple2)
    )

def maxAverageOfPath(matrix):
    n = len(matrix)
    if n == 0:
        return 0.0

    # DP table to store maximum sum to reach each cell
    dp = [[0] * n for _ in range(n)]
    dp[0][0] = matrix[0][0]

    # Fill first column
    for i in range(1, n):
        dp[i][0] = dp[i-1][0] + matrix[i][0]

    # Fill first row
    for j in range(1, n):
        dp[0][j] = dp[0][j-1] + matrix[0][j]

    # Fill rest of the DP table
    for i in range(1, n):
        for j in range(1, n):
            dp[i][j] = max(dp[i-1][j], dp[i][j-1]) + matrix[i][j]

    max_sum = dp[n-1][n-1]
    # Number of cells visited in any path = (2*n - 1)
    return max_sum / (2 * n - 1)

def largest_smallest_integers(lst):
    '''
    Create a function that returns a tuple (a, b), where 'a' is
    the largest of negative integers, and 'b' is the smallest
    of positive integers in a list.
    If there is no negative or positive integers, return them as None.

    Examples:
    largest_smallest_integers([2, 4, 1, 3, 5, 7]) == (None, 1)
    largest_smallest_integers([]) == (None, None)
    largest_smallest_integers([0]) == (None, None)
    '''
    a = None
    b = None
    for num in lst:
        if num < 0:
            if a is None or num > a:
                a = num
        elif num > 0:
            if b is None or num < b:
                b = num
    return (a, b)

def count_up_to(n):
    """Implement a function that takes a non-negative integer and returns an array of the first n
    integers that are prime numbers and less than n.
    for example:
    count_up_to(5) => [2,3]
    count_up_to(11) => [2,3,5,7]
    count_up_to(0) => []
    count_up_to(20) => [2,3,5,7,11,13,17,19]
    count_up_to(1) => []
    count_up_to(18) => [2,3,5,7,11,13,17]
    """
    def is_prime(num):
        if num < 2:
            return False
        for i in range(2, int(num ** 0.5) + 1):
            if num % i == 0:
                return False
        return True

    return [x for x in range(2, n) if is_prime(x)]

def histogram(test):
    """Given a string representing a space separated lowercase letters, return a dictionary
    of the letter with the most repetition and containing the corresponding count.
    If several letters have the same occurrence, return all of them.

    Example:
    histogram('a b c') == {'a': 1, 'b': 1, 'c': 1}
    histogram('a b b a') == {'a': 2, 'b': 2}
    histogram('a b c a b') == {'a': 2, 'b': 2}
    histogram('b b b b a') == {'b': 4}
    histogram('') == {}

    """
    if not test:
        return {}
    words = test.split()
    counts = {}
    for word in words:
        counts[word] = counts.get(word, 0) + 1
    max_count = max(counts.values())
    return {letter: count for letter, count in counts.items() if count == max_count}

def match_parens(lst):
    def is_balanced(s):
        balance = 0
        for ch in s:
            if ch == '(':
                balance += 1
            else:
                balance -= 1
            if balance < 0:
                return False
        return balance == 0

    s1, s2 = lst[0], lst[1]
    return 'Yes' if is_balanced(s1 + s2) or is_balanced(s2 + s1) else 'No'

from collections import Counter

def search(lst):
    freq = Counter(lst)
    best = -1
    for num in freq:
        if freq[num] >= num and num > best:
            best = num
    return best

def get_row(lst, x):
    result = []
    for row_idx, row in enumerate(lst):
        cols = [col_idx for col_idx, val in enumerate(row) if val == x]
        cols.sort(reverse=True)
        for col_idx in cols:
            result.append((row_idx, col_idx))
    return result
